// @ThomasYou
sort = [];
push = (title, url, type) => sort.push({
    title: title,
    url: url,
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: type
    }
});
$$ = (path, arr, uType) => {
    switch (uType) {
        case 'pg':
            arr.push("pg=$page", "pz=20");
            break;
        case 'top':
            arr.push("version=", "pageIndex=$page", "pageSize=20");
            break;
    }
    arr = JSON.stringify(arr, null, "\t");
    return `@js:QDSign("${path}", ${arr}, page)`;
}






push("主编力荐", $$("v1/square/morepage", ["itemId=387"], "pg"), 0.4);
push("畅销精选", $$("v1/square/morepage", ["itemId=386"], "pg"), 0.4);
