.mainbody>.index>dt, 
.mainbody>.index>dd
@js:
eval(String(source.loginUrl));
list=[];
$=result;
for(i in $){
if(String($[i]).match(/atitle|dt/)){
	if(String($[i]).match(/atitle/)){
		text="📖【"+$[i].text()+"】📖";
		info1= "";
		}
		else{
			text= "🏮〖"+$[i].text()+"〗🏮";
	  	info1= $[i].text()+" · ";
		}
		if(分卷) list.push({
				text: text,
				volume: true
			});			
		}
else{  
		$[i].select("a").forEach(a=>{	
	jm=java.getString("dt@text");
	title=a.attr("title");	
 word=	title.match(/共(\d+)字/);
		if(jm&&word[1]==0){
			text="";href="";info="";
		}	
		else{
			text= a.text();
			href=a.attr("href");
			info= info1+word[0];
		}
				list.push({	
						text: text,
						href: href,
			   	info: info,
					})
			})
	}
}
