@js:
(function() {
    var list = [];
    var now = new Date().getTime();
    var usr = Math.floor(Math.random() * 90000000 + 10000000);
    function getRankUrl(sectionId) {
        var s = sign('timestamp=' + now + '&usr=' + usr);
        return 'https://dj.palmestore.com/zybk/api/category/tagbook?usr=' + usr + '&sign=' + encodeURIComponent(s) + '&pageSize=20&sectionId=' + sectionId + '&currentPage={{page}}&timestamp=' + now + '&p3=25255056&freqKey=-1&today=0';
    }
    function getTagUrl(tagId) {
        var s = sign('timestamp=' + now + '&usr=' + usr);
        return 'https://dj.palmestore.com/zybk/api/category/data?usr=' + usr + '&tagId=' + tagId + '&isTop=1&sign=' + encodeURIComponent(s) + '&tagType=2&page={{page}}&timestamp=' + now + '&p3=25255056&p4=501656&p5=19&p21=3&p22=10&p25=25255156&p26=29&p28=f1a07127cc32ede2';
    }
    function addItem(title, url) {
        list.push({
            title: title,
            url: url,
            style: {
                layout_flexGrow: 1,
                layout_flexBasisPercent: 0.25
            }
        });
    }
    function addTitle(title) {
        list.push({
            title: title,
            url: null,
            style: {
                layout_flexGrow: 1,
                layout_flexBasisPercent: 1
            }
        });
    }
