<js>
m=String(result).match(/(\/.+all_)/);
if(m==null){result=null;}
else{m=m[1];
n=String(result).match(/all_(\d+)/)[1];
n=parseInt(n);page=[];
for(i=2;i<n+1;i++){page[i-2]=m+String(i)+".html"};
result=page;}
</js>

